def _multiply_seq_by_int(
    self: _TupleListNodeT,
    opnode: nodes.AugAssign | nodes.BinOp,
    value: int,
    context: InferenceContext,
) -> _TupleListNodeT:
    node = self.__class__(parent=opnode)
    if value <= 0 or not self.elts:
        # Return empty list for non-positive multiplier or empty list
        node.elts = []
        return node
    if len(self.elts) * value > 1e8:
        node.elts = [util.Uninferable]
        return node
    filtered_elts = (
        util.safe_infer(elt, context) or util.Uninferable
        for elt in self.elts
        if not isinstance(elt, util.UninferableBase)
    )
    try:
        node.elts = list(filtered_elts) * value
    except (OverflowError, MemoryError):
        # Handle case where value is too large to be used as a multiplier
        # For an empty list, this should still be an empty list
        if not self.elts:
            node.elts = []
        else:
            # For non-empty lists with very large multipliers, mark as uninferable
            node.elts = [util.Uninferable]
    return node

